def count_status(lines):
    d = {}
    for line in lines:
        s = line.split()[-1]
        d[s] = d.get(s, 0) + 1
    items = sorted(d.items(), key=lambda kv: (-kv[1], kv[0]))
    return [[k, v] for k, v in items]

def perm_to_octal(s):
    out = ''
    for i in range(0, 9, 3):
        n = 0
        if s[i] == 'r':
            n += 4
        if s[i + 1] == 'w':
            n += 2
        if s[i + 2] == 'x':
            n += 1
        out += str(n)
    return out

def human_users(text):
    out = []
    for line in text.split('\n'):
        if not line:
            continue
        f = line.split(':')
        if int(f[2]) >= 1000:
            out.append(f[0])
    return out

def hog(lines):
    best = ''
    top = -1.0
    for line in lines:
        f = line.split()
        c = float(f[1])
        if c > top:
            top = c
            best = f[0]
    return best

