def to_bits(ip):
    out = ''
    for p in ip.split('.'):
        b = bin(int(p))[2:]
        out += '0' * (8 - len(b)) + b
    return out


def in_subnet(ip, cidr):
    net, n = cidr.split('/')
    n = int(n)
    return to_bits(ip)[:n] == to_bits(net)[:n]

